<script setup lang="ts">
import {onMounted,ref} from 'vue';import {message} from 'ant-design-vue';import {api,type Space} from '@/api/gallery';const spaces=ref<Space[]>([]),busy=ref(false),members=ref(false),current=ref<Space>(),list=ref<{id:string;name:string;role:string}[]>([]);async function load(){try{spaces.value=await api('/space/mine',undefined,'GET')}catch(e){message.error((e as Error).message)}}async function create(type:number){const name=prompt(type?'团队空间名称':'个人空间名称');if(!name)return;busy.value=true;try{await api('/space/add',{spaceName:name,spaceType:type});message.success('空间已创建');await load()}catch(e){message.error((e as Error).message)}finally{busy.value=false}}async function manage(s:Space){current.value=s;members.value=true;try{list.value=(await api<any[]>(`/space/members?id=${s.id}`,undefined,'GET')).map(x=>({id:String(x.userId),name:String(x.userId),role:x.spaceRole}))}catch(e){message.error((e as Error).message)}}async function addMember(){const userId=prompt('输入成员用户 ID');if(!userId)return;const spaceRole=prompt('权限：viewer、editor 或 admin','editor');if(!spaceRole)return;try{await api('/space/member',{id:current.value!.id,userId,spaceRole});await manage(current.value!)}catch(e){message.error((e as Error).message)}}async function changeRole(member:{id:string;role:string}){const spaceRole=prompt('新权限：viewer、editor 或 admin',member.role);if(!spaceRole)return;try{await api('/space/member',{id:current.value!.id,userId:member.id,spaceRole});await manage(current.value!)}catch(e){message.error((e as Error).message)}}async function remove(member:{id:string}){try{await api('/space/member/delete',{id:current.value!.id,userId:member.id});await manage(current.value!)}catch(e){message.error((e as Error).message)}}onMounted(load)
</script><template><div class="page-heading"><span class="eyebrow">YOUR WORKSPACES</span><h1>每个灵感，都有自己的空间。</h1><p class="muted">创建个人或团队图库，邀请伙伴一起管理素材。</p></div><div class="space-actions"><a-button @click="create(0)">＋ 新建个人空间</a-button><a-button type="primary" @click="create(1)">＋ 新建团队空间</a-button></div><a-spin :spinning="busy"><div class="spaces-grid"><article v-for="s in spaces" :key="s.id" class="space-card"><div class="space-symbol">{{s.spaceType===1?'✦':'▤'}}</div><span class="eyebrow">{{s.spaceType===1?'TEAM SPACE':'PERSONAL SPACE'}} · LEVEL {{s.spaceLevel}}</span><h2>{{s.spaceName}}</h2><p>{{s.totalCount}} 张图片 · {{(Number(s.totalSize)/1024/1024).toFixed(1)}} MB 已用</p><div class="space-progress"><span :style="{width:`${Math.min(100,Number(s.totalSize)/Number(s.maxSize)*100)}%`}"/></div><a-space><RouterLink :to="`/space/${s.id}`"><a-button type="primary">打开图库</a-button></RouterLink><a-button v-if="s.spaceType===1" @click="manage(s)">团队成员</a-button><RouterLink :to="`/analysis?spaceId=${s.id}`"><a-button>分析</a-button></RouterLink></a-space></article></div><a-empty v-if="!spaces.length" description="还没有空间。创建一个，开始整理你的图库吧。"/></a-spin><a-modal v-model:open="members" :title="`${current?.spaceName} · 成员管理`" @ok="addMember" ok-text="添加成员"><a-list :data-source="list"><template #renderItem="{item}"><a-list-item><template #actions><a @click="changeRole(item)">调整权限</a><a @click="remove(item)">移除</a></template>用户 {{item.name}}<a-tag>{{item.role}}</a-tag></a-list-item></template></a-list><p class="muted">viewer 可查看，editor 可编辑图片，admin 可管理成员。</p></a-modal></template>
